import Controller from "sap/ui/core/mvc/Controller";
import MessageToast from "sap/m/MessageToast";
import formatter from "../model/formatter";

/**
 * @namespace my.app.controller
 */
export default class Main extends Controller {
  public formatter = formatter;

  public onPress(): void {
    MessageToast.show("Hello");
  }
}
// the UI5 TypeScript build turns these imports into sap.ui.define([...], function (...) { ... })

sap.ui.define([
  "sap/ui/core/mvc/Controller"
], function (Controller) {
  "use strict";

  return Controller.extend("my.app.controller.Main", {
    onDeletePress: function () {
      // MessageBox is loaded only when the user presses Delete
      sap.ui.require(["sap/m/MessageBox"], function (MessageBox) {
        MessageBox.confirm("Delete this item?");
      });
    }
  });
});

// promise style for on-demand loading
const [Spreadsheet] = await new Promise((resolve, reject) =>
  sap.ui.require(["sap/ui/export/Spreadsheet"], (...modules) => resolve(modules), reject)
);

// synchronous lookup: ONLY returns a module that is already loaded
const MessageBox = sap.ui.require("sap/m/MessageBox");   // may be undefined

// in an XML view:
// <mvc:View core:require="{ formatMessage: 'sap/base/strings/formatMessage' }" ...>

// Generic AMD (for example RequireJS)
define(["./helper"], function (helper) {
  return { run: helper.run };
});

// The same in SAPUI5
sap.ui.define(["./helper"], function (helper) {
  "use strict";
  return { run: helper.run };
});
